// Сверка с Hebcal (geonameid 293397 תל אביב, 293788 רמת גן): тест сам делает HTTP-запрос к hebcal.com из Node.
// Кейсы: .qa/tests/readiness/RD-05-zmanim-dates.md. Дополняет ZM-01/02/05 (формат строк, навигация).
import { expect, driver } from '@wdio/globals';
import { byText, byTextContains, scrollToText } from '../../helpers/ui.ts';
import { skipWith, shown } from '../_lib/app-0710.ts';
import { deviceClock } from '../_lib/app-1310b.ts';
import {
  goHome, openZmanim, zmanimGoTo, zmanimDate, zmanimRows, hebcalZmanim, HEBCAL_KEYS, GEONAMES, toMin, nodes,
  openProfile, profileValue, setProfileCity, button, saveArtifact, saveShot,
} from '../_lib/readiness-1910.ts';

const iso = (d: Date) => d.toISOString().slice(0, 10);

/** Сверить времена открытого дня с Hebcal для города; допуск 1 мин (округление). Возвращает список расхождений. */
async function compareWithHebcal(city: string) {
  const id = GEONAMES[city];
  const { date } = await zmanimDate();
  const ref = await hebcalZmanim(id, iso(date));
  const rows = await zmanimRows();
  const diffs: string[] = [];
  let checked = 0;
  for (const r of rows) {
    const key = HEBCAL_KEYS[`${r.name}|${r.method.replace(/[‎‏]/g, '')}`];
    if (!key || !ref[key] || r.time === '—') continue;
    checked++;
    const d = Math.abs(toMin(r.time) - toMin(ref[key]));
    if (d > 1) diffs.push(`${r.name} ${r.method}: приложение ${r.time}, Hebcal ${ref[key]}`);
    else if (d === 1) console.log(`[RD-05] ±1 мин: ${r.name} ${r.method} ${r.time} / ${ref[key]}`);
  }
  saveArtifact(`zmanim-${id}-${iso(date)}.json`, { city, rows, ref });
  console.log(`[RD-05] ${city} ${iso(date)}: сверено ${checked} строк`);
  expect(checked).toBeGreaterThanOrEqual(12);
  return diffs;
}

describe('Готовность 19.10 — זמנים и даты', () => {
  afterEach(async () => { await goHome().catch(() => {}); });

  it('RD-05a Переход месяца: 10.11.2026 «ל׳ חשון תשפ״ז» → «היום הבא» → 11.11.2026 «א׳ כסלו תשפ״ז» (= Hebcal) F-94 AC2 @prod-safe', async function () {
    this.timeout(600000);
    await openZmanim();
    await zmanimGoTo(2026, 11, 10);
    expect((await zmanimDate()).heb).toBe('ל׳ חשון תשפ״ז');
    await (await button('היום הבא')).click();
    await driver.waitUntil(async () => (await zmanimDate()).greg === '11 בנובמבר 2026', { timeout: 10000, timeoutMsg: 'не 11 בנובמבר' });
    expect((await zmanimDate()).heb).toBe('א׳ כסלו תשפ״ז');
  });

  it('RD-05b Переход года: 1.10.2027 «כ״ט אלול תשפ״ז» → «היום הבא» → 2.10.2027 «א׳ תשרי תשפ״ח» («השנה הבאה» + дни) F-94 AC2 @prod-safe', async function () {
    this.timeout(600000);
    await openZmanim();
    await zmanimGoTo(2027, 10, 1);
    expect((await zmanimDate()).heb).toBe('כ״ט אלול תשפ״ז');
    await (await button('היום הבא')).click();
    await driver.waitUntil(async () => (await zmanimDate()).greg === '2 באוקטובר 2027', { timeout: 10000, timeoutMsg: 'не 2 באוקטובר 2027' });
    expect((await zmanimDate()).heb).toBe('א׳ תשרי תשפ״ח');
  });

  it('RD-05c Времена города профиля (תל אביב / רמת גן) на сегодня = Hebcal (±1 мин), место расчёта показано F-94 AC3 F-44 AC1 @prod-safe', async function () {
    await openProfile();
    await scrollToText('מיקום');
    const city = await profileValue('מיקום');
    if (!GEONAMES[city]) skipWith(this, `город профиля «${city}» без geonameid в тесте (есть: ${Object.keys(GEONAMES).join(', ')})`);
    await openZmanim();
    await expect(byTextContains(`הזמנים חושבו עבור ${city}`)).toBeDisplayed({ wait: 20000 });
    expect(await compareWithHebcal(city)).toEqual([]);
  });

  it('RD-05d Второй город: профиль → «רמת גן» (или «תל אביב») → времена пересчитаны и = Hebcal; исходный город возвращён F-46 AC3 F-94 AC3 @data', async function () {
    this.timeout(900000);
    await openProfile();
    await scrollToText('מיקום');
    const orig = await profileValue('מיקום');
    const other = orig === 'רמת גן' ? 'תל אביב' : 'רמת גן';
    try {
      await setProfileCity(other);
      await openZmanim();
      await expect(byTextContains(`הזמנים חושבו עבור ${other}`)).toBeDisplayed({ wait: 20000 });
      expect(await compareWithHebcal(other)).toEqual([]);
    } finally {
      await setProfileCity(orig);
      await openZmanim();
      await expect(byTextContains(`הזמנים חושבו עבור ${orig}`)).toBeDisplayed({ wait: 20000 });
    }
  });

  it('RD-05e После заката: «ערב טוב», ближайшая «ערבית», «התחל תפילה» активна; «הנחת תפילין» нет в «תזכורות מהירות»; скрин шапки (луна, «ט׳ חשון», окно «18:04 - 05:35») для сверки S-32 F-47 AC5 @time @prod-safe @manual-check', async function () {
    await openZmanim();
    const rows = await zmanimRows();
    const sunset = rows.find((r) => r.name === 'שקיעת החמה')?.time;
    const now = await deviceClock();
    if (!sunset || now.h * 60 + now.m < toMin(sunset) + 2) skipWith(this, `запуск после заката (сегодня ${sunset ?? '?'}), сейчас ${now.h}:${String(now.m).padStart(2, '0')}`);
    if (now.h < 12) skipWith(this, 'после полуночи — другой день, запускать вечером до 24:00');
    await goHome();
    await expect(byTextContains('ערב טוב')).toBeDisplayed({ wait: 20000 });
    // Ближайшая молитва — крупный текст под приветствием (S-32: «ערבית», y=202).
    const title = (await nodes()).filter((n) => ['שחרית', 'מנחה', 'ערבית'].includes(n.label) && n.y < 400).sort((a, b) => a.y - b.y)[0]?.label;
    expect(title).toBe('ערבית');
    expect(await (await button('התחל תפילה')).isEnabled()).toBe(true);
    // Дата, окно «<שקיעה> - <עלות>» и луна в шапке не имеют подписи доступности — скрин для сверки человеком.
    console.log(`[RD-05e] скрин: ${await saveShot('S-32-evening-home.png')} — ожидается еврейская дата следующего дня, «${sunset} - …», луна`);
    // F-47 AC5: «הנחת תפילין» исчезает после заката (при включённых напоминаниях).
    await scrollToText('תזכורות מהירות');
    if (await shown(byTextContains('התזכורות כבויות'))) skipWith(this, 'напоминания выключены — F-47 AC5 не проверить (включить «תזכורות והתראות»)');
    expect(await shown(byText('הנחת תפילין'))).toBe(false);
  });
});
